-- ============================================================
CREATE TABLE IF NOT EXISTS saee_ativos (
    id                SERIAL PRIMARY KEY,
    seq_planilha      INTEGER,
    num_ativo         VARCHAR(20),
    local             VARCHAR(50),
    sublocal          VARCHAR(60),
    sistema           VARCHAR(80),
    nome_ativo        VARCHAR(200),
    tag               VARCHAR(50),
    esp_tecnica       VARCHAR(200),
    tag_diagrama      VARCHAR(50),
    diagrama          VARCHAR(100),
    item_contrato     VARCHAR(20),
    periodicidade     VARCHAR(20),
    area              VARCHAR(20),
    data_ult_manu     DATE,
    proxima_manu      DATE,
    ativo             BOOLEAN DEFAULT TRUE,
    created_at        TIMESTAMP DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_saee_ativos_sublocal      ON saee_ativos(sublocal);
CREATE INDEX IF NOT EXISTS idx_saee_ativos_sistema       ON saee_ativos(sistema);
CREATE INDEX IF NOT EXISTS idx_saee_ativos_periodicidade ON saee_ativos(periodicidade);
CREATE INDEX IF NOT EXISTS idx_saee_ativos_proxima_manu  ON saee_ativos(proxima_manu);
CREATE INDEX IF NOT EXISTS idx_saee_ativos_tag           ON saee_ativos(tag);

