-- ============================================================
-- PASSO 3: Verificar importação
-- ============================================================
SELECT COUNT(*) as total, sistema, periodicidade
FROM saee_ativos
GROUP BY sistema, periodicidade
ORDER BY sistema, periodicidade;

-- Ativos com manutenção vencida (proxima_manu < hoje):
SELECT COUNT(*) as vencidos FROM saee_ativos WHERE proxima_manu < CURRENT_DATE;

-- Ativos com manutenção nos próximos 30 dias:
SELECT COUNT(*) as proximos_30d FROM saee_ativos WHERE proxima_manu BETWEEN CURRENT_DATE AND CURRENT_DATE + 30;
